@staticmethod
def _load_file(path):
    try:
        if path == '-':
            content = sys.stdin.read()
        else:
            # Try multiple encodings, prioritizing 'utf-8-sig' to handle BOM properly
            from codecs import open as codecs_open
            # always try 'utf-8-sig' first, so that BOM in WinOS won't cause trouble.
            for encoding in ('utf-8-sig', 'utf-8', 'utf-16', 'utf-16le', 'utf-16be'):
                try:
                    with codecs_open(os.path.expanduser(path), encoding=encoding) as input_file:
                        content = input_file.read()
                        break
                except UnicodeError:
                    continue
            else:
                # If all encodings fail, fall back to binary read
                with open(os.path.expanduser(path), 'rb') as input_file:
                    content = input_file.read()
        return content[0:-1] if content[-1] == '\n' else content
    except:
        raise CLIError('Failed to open file {}'.format(path))
